css:
.fx-art{position:relative;overflow:hidden;background:linear-gradient(135deg,var(--primary),color-mix(in srgb,var(--primary) 45%,var(--accent)))}
.fx-art::before,.fx-art::after{content:"";position:absolute;border-radius:50%;background:color-mix(in srgb,var(--accent) 60%,#fff);opacity:.35}
.fx-art::before{width:60%;aspect-ratio:1;right:-12%;top:-20%}.fx-art::after{width:38%;aspect-ratio:1;left:8%;bottom:-18%;opacity:.25;background:#fff}
.fx-art.a2{background:linear-gradient(160deg,var(--accent),color-mix(in srgb,var(--accent) 40%,var(--primary)))}
.fx-art.a3{background:linear-gradient(200deg,color-mix(in srgb,var(--primary) 70%,#000),var(--accent))}
.fx-spot .grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:1.6em;width:min(1060px,100%)}
.fx-spot .card{background:color-mix(in srgb,var(--surface) 94%,var(--text));border:1px solid var(--border);border-radius:var(--radius);overflow:hidden;display:flex;flex-direction:column}
.fx-spot .card .fx-art{aspect-ratio:16/10}
.fx-spot .card .body{padding:1.2em 1.3em 1.4em;display:grid;gap:.55em}
.fx-spot .card .tag{justify-self:start;font-size:.72em;font-weight:700;letter-spacing:.1em;text-transform:uppercase;color:var(--accent)}
.fx-spot .card h3{font-size:1.35em}.fx-spot .card p{opacity:.7;font-size:.95em}
.fx-spot .card a{color:var(--primary);font-weight:700;text-decoration:none;font-size:.92em;margin-top:.3em}
@media(max-width:820px){.fx-spot .grid{grid-template-columns:1fr}}
.fx-spot .card{position:relative;isolation:isolate}
.fx-spot .card::before{content:"";position:absolute;inset:0;z-index:2;pointer-events:none;opacity:0;transition:opacity .35s;background:radial-gradient(360px circle at var(--mx,50%) var(--my,50%),color-mix(in srgb,var(--accent) 26%,transparent),transparent 62%)}
.fx-spot .card:hover::before{opacity:1}.fx-spot .card:hover{border-color:color-mix(in srgb,var(--accent) 55%,var(--border))}
/* touch: :hover mirrored as .is-tap */
.fx-spot .card.is-tap::before{opacity:1}
.fx-spot .card.is-tap{border-color:color-mix(in srgb,var(--accent) 55%,var(--border))}

js:
document.querySelectorAll('.fx-spot .card').forEach(function(c){c.addEventListener('pointermove',function(e){var r=c.getBoundingClientRect();c.style.setProperty('--mx',e.clientX-r.left+'px');c.style.setProperty('--my',e.clientY-r.top+'px')})});
/* touch: light follows the tap */
document.querySelectorAll('.fx-spot .card').forEach(function(c){c.addEventListener('pointerdown',function(e){var r=c.getBoundingClientRect();c.style.setProperty('--mx',e.clientX-r.left+'px');c.style.setProperty('--my',e.clientY-r.top+'px')})});

/* fx-touch */
(function(){if(window.__fxTap)return;window.__fxTap=1;var cur=[];function clr(){cur.forEach(function(e){e.classList.remove('is-tap')});cur=[]}
document.addEventListener('pointerdown',function(e){if(e.pointerType!=='touch')return;clr();var n=e.target.closest&&e.target.closest('.fx');if(!n)return;for(var el=e.target;el&&el!==n.parentNode;el=el.parentNode){if(el.classList){el.classList.add('is-tap');cur.push(el)}}},{passive:true});
document.addEventListener('pointerup',function(){setTimeout(clr,1400)},{passive:true})})();
